function decorateReview(){
 $('quiz').insertAdjacentHTML('afterbegin',reviewToolbar());
 const meta=$('quiz').querySelector('.q-meta');if(meta){const spans=meta.querySelectorAll('span');if(spans[2])spans[2].textContent='Preview · no scoring';}
 $('flag-question')?.remove();$('skip-question')?.remove();$('round-overview')?.remove();
 $('quiz').querySelector('.action-left').innerHTML='<span class="review-no-answers">Try the controls. No answer needs to be submitted.</span>';
 for(const selector of ['.round-progress','.format-progress','.round-nav','.flagged-list']){const el=$('quiz').querySelector(selector);if(el)el.hidden=true;}
 if(reviewKey){const q=current();$('feedback-area').innerHTML='<section class="teacher-solution"><span class="eyebrow">TEACHING NOTES · '+esc(q.id)+'</span><h3>Answer & reasoning</h3><p><b>'+esc(C.answerText(q))+'</b></p><p>'+esc(q.explanation)+'</p><p><b>Prompt for discussion: </b>'+esc(q.hint)+'</p><p class="tiny-note">Curriculum references: '+q.refs.map(esc).join(', ')+'</p></section>';}
 $('share-mode').value=shareMode;$('share-mode').onchange=ev=>{shareMode=ev.target.value;};$('review-close').onclick=closeReview;$('review-apply').onclick=()=>reviewApplyFilters();$('review-reset').onclick=()=>reviewApplyFilters(true);$('review-type').onchange=()=>reviewApplyFilters();$('review-group').onchange=()=>reviewApplyFilters();$('review-visual').onchange=()=>reviewApplyFilters();$('review-search').onkeydown=ev=>{if(ev.key==='Enter'){ev.preventDefault();reviewApplyFilters();}};
 $('review-jump').onchange=ev=>{run.pos=run.queue.indexOf(ev.target.value);selected=null;renderQuestion();};$('review-index').ontoggle=ev=>{reviewIndexOpen=ev.target.open;};
 $('quiz').querySelectorAll('[data-review-id]').forEach(b=>b.onclick=()=>{run.pos=run.queue.indexOf(b.dataset.reviewId);selected=null;renderQuestion();document.querySelector('.question-card').scrollIntoView({block:'start'});});
 $('quiz').querySelectorAll('[data-select-question]').forEach(b=>b.onchange=()=>{if(b.checked)reviewSelection.add(b.dataset.selectQuestion);else reviewSelection.delete(b.dataset.selectQuestion);$('selection-count').textContent=reviewSelection.size+' selected';});
 $('select-filtered').onclick=()=>{run.queue.forEach(id=>reviewSelection.add(id));renderQuestion();};$('clear-selection').onclick=()=>{reviewSelection.clear();renderQuestion();};$('review-key').onchange=ev=>{reviewKey=ev.target.checked;renderQuestion();};$('copy-set').onclick=copyPracticeLink;$('print-set').onclick=printPracticeSet;
 $('check-answer').onclick=()=>{if(run.pos<run.queue.length-1)navigate(1);else{$('review-index').open=true;$('review-index').scrollIntoView({behavior:'smooth',block:'start'});}};
}

function renderTeacher(){const seen=stats(),t=activeTopic();$('teacher-content').innerHTML='<p class="intro">'+D.questions.length+' original '+t.name+' questions across '+D.groups.length+' KUSP groups. Each group has two questions in each of nine formats. Progress below belongs to this device.</p><div class="table-scroll"><table class="coverage-table"><thead><tr><th>Learning goal</th><th>Questions</th><th>Seen</th><th>Correct at least once</th></tr></thead><tbody>'+D.groups.map(g=>{const s=stats(D.questions.filter(q=>q.group===g.id));return'<tr><td>'+esc(g.title)+'</td><td>'+D.questions.filter(q=>q.group===g.id).length+'</td><td>'+s.seen+'</td><td>'+s.correct+'</td></tr>';}).join('')+'</tbody></table></div><h3>Question-format exposure</h3><div class="table-scroll"><table class="coverage-table"><thead><tr><th>Format</th><th>Available</th><th>Seen</th><th>Correct at least once</th></tr></thead><tbody>'+C.TYPES.map(t=>{const qs=D.questions.filter(q=>q.type===t),s=stats(qs);return'<tr><td>'+FORMAT[t]+'</td><td>'+qs.length+'</td><td>'+s.seen+'</td><td>'+s.correct+'</td></tr>';}).join('')+'</tbody></table></div><div class="hands-on"><strong>Hands-on outcomes need hands-on evidence.</strong><br>These questions assess the reasoning, planning, safety, and interpretation involved in an investigation. They do not mark conducting an experiment, researching a community decision, or building a device as completed. Use a supervised physical investigation to gather that evidence.</div>'+D.groups.map(g=>'<details class="teacher-group"><summary>'+esc(g.title)+' · curriculum statements</summary>'+['K','U','SP'].map(section=>'<div class="source-section">'+({K:'Knowledge',U:'Understanding',SP:'Skills & Procedures'}[section])+'</div>'+g.source[section].map((s,i)=>{const ref=g.id+'.'+section+(i+1),qs=D.questions.filter(q=>q.refs.includes(ref)),n=qs.filter(q=>progress[q.id]?.seen).length;return'<div class="source-outcome">'+esc(s)+'<small>'+qs.length+' mapped questions · '+n+' seen · '+esc(ref)+'</small></div>';}).join('')).join('')+'<div class="hands-on"><strong>Suggested supervised investigation</strong><br>'+esc(g.handsOn||({particles:'Compare the mass of the same leak-proof closed container before and after ice melts. Keep the setup closed and account for the whole system.',temperature:'With teacher-approved materials and safe water temperatures, design a model that shows liquid expansion in a narrow tube. Compare its response with a proper thermometer; do not treat an uncalibrated model as an accurate instrument.',expansion:'Compare equal masses of liquid water and ice using suitable freezer-safe equipment with expansion space, then relate volume to density. Use a supervised float test as supporting evidence.'}[g.id])||'Use a supervised investigation to gather evidence of this practical outcome.')+'</div></details>').join('')+'<p class="tiny-note">Curriculum mapping follows the '+t.name+' section of Science 1–6 Curriculum NEW Alberta supplied by Darren. The app is independent of Alberta Education and Vretta. “Correct” reports question performance, not mastery of an entire curriculum statement.</p><button class="secondary reset-progress" id="reset-progress">Clear '+t.name+' progress on this device</button><p id="reset-note" class="tiny-note" role="status"></p>';
$('reset-progress').onclick=()=>{if(!resetArmed){resetArmed=true;$('reset-note').textContent='Press the button again to clear '+t.name+' question history and its saved round on this device. Other topics will be kept.';$('reset-progress').textContent='Confirm clear '+t.name+' progress';return;}progress={};run=null;resetArmed=false;persist();renderTeacher();renderSidebar();setView('home');};}
$('help-open').onclick=()=>$('help-dialog').showModal();$('round-close').onclick=()=>$('round-dialog').close();$('help-close').onclick=()=>$('help-dialog').close();
$('teacher-open').onclick=()=>{if(reviewMode)closeReview();resetArmed=false;renderTeacher();$('teacher-dialog').showModal();};$('teacher-review').onclick=openReview;$('teacher-close').onclick=()=>$('teacher-dialog').close();$('topics-toggle').onclick=()=>{const open=$('sidebar').classList.toggle('open');$('topics-toggle').setAttribute('aria-expanded',String(open));};$('start-menu').onclick=()=>{if(reviewMode)closeReview();else{persist();setView('home');}};$('home-button').onclick=()=>{if(reviewMode)closeReview();else setView('home');};$('leave-cancel').onclick=()=>{pendingStart=null;pendingQueue=null;$('leave-dialog').close();};$('leave-confirm').onclick=()=>{const id=pendingStart,custom=pendingQueue;pendingStart=null;pendingQueue=null;$('leave-dialog').close();if(custom)beginQueue(custom.ids,'custom',custom.mode);else begin(id);};document.addEventListener('click',ev=>{const t=ev.target.closest('.unit-tab[data-topic]');if(t){activateTopic(t.dataset.topic);return;}const b=ev.target.closest('[data-start]');if(b&&!reviewMode)start(b.dataset.start);});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();});window.addEventListener('beforeunload',persist);
window.ScienceLab={get data(){return D;},get topics(){return TOPICS.map(t=>({id:t.id,name:t.name,count:t.data.questions.length}));},core:C,getState:()=>clone({topic:topicId,progress,run,settings,view})};
